/**
 * Frozen test set schema.
 *
 * One JSONL file. Each line is a TestCase. Test cases are author-curated;
 * they are NEVER auto-generated by the system being tested.
 *
 * v0.1 spec: tuning never happens on the reporting set. We treat this file
 * as the reporting set; if you need a tuning set, create a parallel file
 * named `tuning-set.jsonl`.
 */

export interface TestCase {
  /** Stable id used in reports. */
  id: string;
  /** Free-text query the user might ask. */
  query: string;
  /**
   * Memory ids that should appear somewhere in the top-K results. At least
   * one of these is the correct answer; multiple ids mean "any of these
   * counts as a hit" (useful when the same fact is stored in multiple
   * markdown files).
   */
  expectedMemoryIds: string[];
  /** Author intent label, used for slicing reports. */
  intent: "decision_recall" | "fact_recall" | "preference_recall" | "event_recall" | "negative";
  /** Optional human notes that explain why this case matters. */
  notes?: string;
  /** Optional max top-K to consider; defaults to 5. */
  k?: number;
}

export interface TestSet {
  cases: TestCase[];
  /** Path the cases were loaded from. */
  source: string;
}
